import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"Privacy Policy","description":"","frontmatter":{},"headers":[],"relativePath":"guide/privacy.md","filePath":"guide/privacy.md","lastUpdated":1784988047000}`),a={name:`guide/privacy.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="privacy-policy" tabindex="-1">Privacy Policy <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to “Privacy Policy”">​</a></h1><p>Minesweeper is an offline-first application. This page explains what (if any) data the app collects and how it is used.</p><h2 id="offline-first-—-no-data-collection" tabindex="-1">Offline-First — No Data Collection <a class="header-anchor" href="#offline-first-—-no-data-collection" aria-label="Permalink to “Offline-First — No Data Collection”">​</a></h2><ul><li>The core game is 100% offline. No network access is required to play.</li><li>All game data — settings, game state, and statistics — is stored locally on your device.</li><li>Your game data never leaves your device. Nothing is uploaded, transmitted, or shared.</li><li>There are no ads, no analytics, and no tracking.</li></ul><h2 id="the-only-network-access-more-apps" tabindex="-1">The Only Network Access: &quot;More Apps&quot; <a class="header-anchor" href="#the-only-network-access-more-apps" aria-label="Permalink to “The Only Network Access: &quot;More Apps&quot;”">​</a></h2><p>The sole network feature is an optional <strong>&quot;More Apps&quot;</strong> section in Settings, which fetches a list of sibling apps from our servers. This feature:</p><ul><li>Only activates when you navigate to Settings → More Apps.</li><li>Fetches a lightweight list of app names and links — no personal data is sent or stored.</li><li>Can be completely ignored and does not affect gameplay in any way.</li></ul><p>No other network access occurs during normal gameplay.</p><h2 id="what-we-do-not-collect" tabindex="-1">What we do not collect <a class="header-anchor" href="#what-we-do-not-collect" aria-label="Permalink to “What we do not collect”">​</a></h2><ul><li>We do not collect personal information, files, images, or browsing history.</li><li>We do not send any game data to external servers.</li><li>We do not include third-party analytics or advertising SDKs.</li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to “Permissions”">​</a></h2><p>Minesweeper does not require any special permissions. No location, no contacts, no camera — nothing. The app works entirely offline from the moment you install it.</p><h2 id="privacy-requests" tabindex="-1">Privacy requests <a class="header-anchor" href="#privacy-requests" aria-label="Permalink to “Privacy requests”">​</a></h2><p>Since Minesweeper stores all data locally on your device and does not transmit personal data, there is no server-side data to access or delete. To clear all app data, simply uninstall the app or use the reset option in Troubleshooting.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to “Contact”">​</a></h2><p>For privacy questions, open an issue at the project repository (<a href="https://github.com/minesweeper-app/minesweeper-site" target="_blank" rel="noreferrer">https://github.com/minesweeper-app/minesweeper-site</a>) or contact the maintainers.</p>`,16)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};